sources.MoreStores.ts:
export class ActualStore {
 read(): string { return 'second-module' }
}
export class SecondOther {
 read(): string { return 'other-second-module' }
}

sources.MissingStores.ts:
export class ActualStore {
 write(): void { send() }
}
export class OtherStore {
 read(): string { return 'must-not-bind' }
}

sources.SecondConsumer.ts:
import { ActualStore as LocalStore } from './MoreStores'
export class SecondConsumer {
 store: LocalStore
 collect(): string {
  return this.store.read()
 }
}

